/*
 * 기본 세계 가게 이름과 메뉴 이름이다 (#886, #905, #941). V3 는 "중식 001호점", "중식 메뉴 1" 같은 자리 이름을 넣고 이 파일이 실제 이름처럼 덮는다.
 * 가게 이름은 업종의 앞말과 뒷말을 조합하거나 대표 메뉴에 역 이름을 붙여 만들었다. 실제 프랜차이즈 상호는 쓰지 않는다.
 * 메뉴 이름은 그 메뉴 사진(world/stores/<가게>/menu-<n>.jpg)에 담긴 음식이다. 같은 가게 안에서는 이름이 겹치지 않는다.
 * 피드 가게(진행 중 캠페인 1 ~ 180, 301 ~ 330 의 가게 210곳)는 메뉴 사진이 가게끼리 겹치지 않고, 메뉴가 없던 52곳에는 메뉴 2개씩을 더한다.
 * 쿠폰 회차와 피드 후보가 복사해 둔 이름도 같이 맞춘다. R__templates_posters 가 이 이름과 사진으로 포스터를 만들어 이 파일이 먼저 돈다.
 * V3 를 고치지 않은 것은 체크섬이 바뀌면 개발과 운영을 다시 정리해야 해서다.
 */

-- 1. 메뉴가 없던 피드 가게의 메뉴와 사진 (52곳 x 2). 번호와 가격은 V3 공식(B + n * 10 + i, 8000 + (n * 500 + i * 1000) % 7000)이다
CREATE TEMPORARY TABLE feed_new_menu (
    store_menu_id BIGINT PRIMARY KEY,
    store_id BIGINT NOT NULL,
    sort_order INT NOT NULL,
    file_size BIGINT NOT NULL
);

SELECT f.store_menu_id, f.store_id, CONCAT('메뉴 ', f.sort_order), 8000 + ((f.store_id - 10000000) * 500 + f.sort_order * 1000) % 7000,
       '대표 메뉴', f.sort_order, s.created_at, s.created_at
FROM feed_new_menu f
JOIN store s ON s.store_id = f.store_id AND s.owner_id BETWEEN 10000001 AND 10000500
ON DUPLICATE KEY UPDATE store_menu.store_menu_id = store_menu.store_menu_id;

                              file_size, upload_status, verified_at, created_at, updated_at)
SELECT f.store_menu_id, f.store_menu_id, CONCAT('0000000b-0000-4000-8000-', LOWER(LPAD(HEX(f.store_menu_id), 12, '0'))),
       CONCAT('world/stores/', f.store_id, '/menu-', f.sort_order, '.jpg'), CONCAT('menu-', f.sort_order, '.jpg'), 'image/jpeg',
       f.file_size, 'VERIFIED', s.created_at, s.created_at, s.created_at
FROM feed_new_menu f
JOIN store s ON s.store_id = f.store_id AND s.owner_id BETWEEN 10000001 AND 10000500
ON DUPLICATE KEY UPDATE store_menu_image.store_menu_image_id = store_menu_image.store_menu_image_id;

DROP TEMPORARY TABLE feed_new_menu;

-- 2. 가게 이름 (기본 세계 가게 488곳, 입점 중 가게 포함)
CREATE TEMPORARY TABLE world_store_name (
    store_id BIGINT PRIMARY KEY,
    name VARCHAR(100) NOT NULL
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- 기본 세계 점주의 가게만 바꾼다
UPDATE store s
JOIN world_store_name w ON w.store_id = s.store_id
SET s.name = w.name
WHERE s.owner_id BETWEEN 10000001 AND 10000500;

DROP TEMPORARY TABLE world_store_name;

-- 3. 메뉴 이름 (기본 세계 메뉴 810개)
CREATE TEMPORARY TABLE world_menu_name (
    store_menu_id BIGINT PRIMARY KEY,
    store_id BIGINT NOT NULL,
    name VARCHAR(20) NOT NULL
) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- 번호가 같아도 가게가 다르면 건드리지 않는다
UPDATE store_menu m
JOIN world_menu_name w ON w.store_menu_id = m.store_menu_id AND w.store_id = m.store_id
SET m.name = w.name;

DROP TEMPORARY TABLE world_menu_name;

-- 피드 가게의 바뀐 메뉴 사진 크기
CREATE TEMPORARY TABLE feed_menu_size (
    store_menu_id BIGINT PRIMARY KEY,
    file_size BIGINT NOT NULL
);

UPDATE store_menu_image i
JOIN feed_menu_size f ON f.store_menu_id = i.store_menu_id
SET i.file_size = f.file_size
WHERE i.object_key LIKE 'world/stores/%';

DROP TEMPORARY TABLE feed_menu_size;

-- 4. 쿠폰 회차와 피드 후보에 복사된 가게 이름과 대상 메뉴 이름
UPDATE coupon_event e
JOIN store s ON s.store_id = e.store_id
LEFT JOIN store_menu m ON m.store_menu_id = e.target_menu_id
SET e.store_name = s.name,
    e.target_menu_name = IF(e.target_menu_id IS NULL, e.target_menu_name, m.name)
WHERE e.campaign_id BETWEEN 10000001 AND 19999999;
UPDATE ad_candidate a
JOIN campaign c ON c.campaign_id = a.campaign_id
JOIN store s ON s.store_id = c.store_id
LEFT JOIN store_menu m ON m.store_menu_id = c.target_menu_id
SET a.store_name = s.name,
    a.discount_menu_name = IF(c.target_menu_id IS NULL, a.discount_menu_name, m.name)
WHERE a.campaign_id BETWEEN 10000001 AND 19999999;
